import { Check, Copy, Play, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useI18n } from "@/i18n";

// Prompts are always in English (image AIs understand English best) — only titles and descriptions are translated
// example = file in public/examples (generated by `npm run examples` from src/examples/art.ts)
const PROMPTS: { title: { en: string; th: string }; text: string; example: string }[] = [
  {
    title: { en: "Game character sprite", th: "ตัวละครในเกม" },
    text: "Pixel art sprite of a cute fried egg mascot with a strip of bacon, 32x32 pixels, front view, full body, limited 16-color palette, crisp hard pixel edges, no anti-aliasing, flat shading, 1px dark outline, plain light background, centered",
    example: "egg-mascot",
  },
  {
    title: { en: "Item icon set", th: "ชุดไอคอนไอเทม" },
    text: "Pixel art icon set of 9 breakfast items (toast, coffee cup, pancakes, croissant, orange juice, waffle, bacon, egg, donut) arranged in a 3x3 grid, each icon 16x16 pixels, consistent limited palette, no anti-aliasing, crisp pixels, plain background",
    example: "icon-set",
  },
  {
    title: { en: "Walk cycle sprite sheet", th: "sprite sheet ท่าเดิน" },
    text: "Pixel art sprite sheet of a small adventurer, side view, 4-frame walk cycle in one row, each frame 32x32 pixels, same character in every frame, 12-color palette, no anti-aliasing, transparent-looking plain background",
    example: "walk-cycle",
  },
  {
    title: { en: "Top-down tileset", th: "tileset มุมมองจากบน" },
    text: "Seamless top-down RPG tileset in pixel art, 16x16 pixel tiles: grass, dirt path, water, sand and stone, laid out on a clean grid, limited earthy palette, no anti-aliasing, crisp pixels",
    example: "tileset",
  },
  {
    title: { en: "Pixel landscape", th: "ฉากวิว pixel art" },
    text: "Pixel art landscape of a sunrise over a sleepy city with mountains, native resolution 160x90 pixels, 32-color palette, ordered dithering in the sky, crisp pixels, no blur, retro 16-bit game style",
    example: "landscape",
  },
  {
    title: { en: "Profile avatar", th: "รูปโปรไฟล์" },
    text: "Pixel art portrait avatar of a programmer wearing headphones and a hoodie, 64x64 pixels, bust shot, limited 16-color palette, crisp hard edges, no anti-aliasing, solid colored background",
    example: "avatar",
  },
];

export function PromptDialog({ open, onClose, onTry }: { open: boolean; onClose: () => void; onTry: (url: string, name: string) => void }) {
  const { t, lang } = useI18n();
  const ref = useRef<HTMLDialogElement>(null);
  const [copied, setCopied] = useState<number | null>(null);

  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    if (open && !d.open) d.showModal();
    if (!open && d.open) d.close();
  }, [open]);

  return (
    <dialog ref={ref} className="prompts" aria-labelledby="prompts-title" onClose={onClose}>
      <div className="prompts-head">
        <h2 id="prompts-title">{t("promptsTitle")}</h2>
        <button className="icon-btn" aria-label={t("close")} data-tip={t("close")} onClick={onClose}>
          <X size={20} aria-hidden />
        </button>
      </div>
      <p>{t("promptsIntro")}</p>
      <ul>
        {PROMPTS.map((p, i) => (
          <li key={i}>
            <img
              className="example"
              src={`/examples/${p.example}.jpg`}
              alt={t("exampleAlt", { title: p.title[lang] })}
              width={120}
              height={120}
              loading="lazy"
            />
            <div className="prompt-body">
              <div className="prompt-title">
                <b>{p.title[lang]}</b>
              </div>
              <code>{p.text}</code>
              <div className="prompt-actions">
                <button
                  className="btn small"
                  data-tip={t("promptCopy")}
                  onClick={async () => {
                    try {
                      await navigator.clipboard.writeText(p.text);
                    } catch {
                      /* clipboard blocked — the user can still select the text manually */
                    }
                    setCopied(i);
                    setTimeout(() => setCopied((c) => (c === i ? null : c)), 1500);
                  }}
                >
                  {copied === i ? <Check size={16} aria-hidden /> : <Copy size={16} aria-hidden />}
                  {copied === i ? t("copied") : t("promptCopy")}
                </button>
                <button className="btn small primary" data-tip={t("tryTip")} onClick={() => onTry(`/examples/${p.example}.jpg`, `${p.example}.jpg`)}>
                  <Play size={16} aria-hidden />
                  {t("tryExample")}
                </button>
              </div>
            </div>
          </li>
        ))}
      </ul>
      <p className="muted">{t("promptTip")}</p>
      <p className="muted">{t("examplesNote")}</p>
    </dialog>
  );
}
